/* Finance: labor and costs, timesheets, pay runs, the crew's pay stubs and the time clock on Today. */
globalThis.createFinanceUI=function(api){
 'use strict';
 const B=Brigly,P=B.payroll,S=B.schedule,{e,button,badge,dateLabel}=api;
 const s=()=>api.state(),me=()=>B.actor(s().role,s().crewId,s().managerId),manager=()=>s().role==='manager';
 const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);
 const whole=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n||0);
 const hrs=m=>(m/60).toLocaleString('en-US',{maximumFractionDigits:1});
 const span=m=>{m=Math.max(0,Math.round(m));return m<60?m+' min':Math.floor(m/60)+' h'+(m%60?' '+m%60+' m':'');};
 const clock=x=>x?new Date(x+':00').toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):'—';
 const range=(from,to)=>dateLabel(from)+' – '+dateLabel(to,{month:'short',day:'numeric',year:'numeric'});
 const name=id=>B.person(id)?.name||'Former team member';
 const today=()=>P.stamp().slice(0,10);
 const plural=(n,word)=>n+' '+(n===1?word:word==='person'?'people':/[^aeiou]y$/.test(word)?word.slice(0,-1)+'ies':word+'s');
 const act=(label,key,id='',style='secondary',extra='')=>button(label,'fin-'+key,id,extra,style);
 const avatar=p=>`<span class="avatar" data-tone="${p?.area==='Bar'?'orange':p?.area==='Kitchen'?'slate':'sage'}">${e(p?.initials||'?')}</span>`;
 const kpi=(label,value,unit,note)=>`<div class="res-kpi"><small>${label}</small><strong>${value}${unit?` <span>${unit}</span>`:''}</strong><p>${note}</p></div>`;
 // One-series bar chart: rounded data ends on the baseline, a hover tip per bar, values in text colors.
 const bars=(rows,format,label)=>{const max=Math.max(1,...rows.map(r=>r.value));return `<div class="fin-chart" role="img" aria-label="${e(label)}">${rows.map(r=>`<div class="fin-col${r.current?' is-current':''}" data-tip="${e(r.tip||r.label+' · '+format(r.value))}" tabindex="0"><div class="fin-track"><i style="height:${Math.max(2,r.value/max*100)}%"></i></div><small>${e(r.label)}</small></div>`).join('')}</div>`;};
 const hbars=(rows,format)=>{const max=Math.max(1,...rows.map(r=>r.value));return rows.map(r=>`<div class="mg-bar" data-tip="${e(r.tip||'')}"><span>${e(r.label)}</span><div><i style="width:${r.value/max*100}%"></i></div><strong>${format(r.value)}</strong></div>`).join('');};
 let tsFrom='',form=null;

 // The pay period that needs attention: the last one until it is paid, then the current one.
 function focus(st){
  const cur=P.period(st,today()),last=P.previousPeriod(st,cur),run=P.runFor(st,last.from);
  return !run||run.status!=='Paid'?{...last,run,ended:true}:{...cur,run:P.runFor(st,cur.from),ended:cur.to<today()};
 }
 const rosterCost=(st,from,to,filter=()=>true)=>st.shifts.filter(x=>x.date>=from&&x.date<=to&&filter(x)).reduce((n,x)=>n+S.metrics(st,x).wages,0);
 const rosterMinutes=(st,from,to,filter=()=>true)=>st.shifts.filter(x=>x.date>=from&&x.date<=to&&filter(x)&&!S.absence(st,x)).reduce((n,x)=>n+S.metrics(st,x).scheduledMinutes,0);
 function weeks(st,n){
  const cur=B.monday(st.date);
  return Array.from({length:n},(_,i)=>{const from=B.addDays(cur,(i-n+1)*7),to=B.addDays(from,6),value=Math.round(rosterCost(st,from,to));return {label:dateLabel(from,{month:'numeric',day:'numeric'}),value,current:i===n-1,tip:`Week of ${dateLabel(from)} · ${whole(value)}`};});
 }
 // Worked so far this week plus what is still scheduled, per person.
 function projection(st){
  const c=P.settings(st),from=B.monday(today()),to=B.addDays(from,6),now=P.stamp();
  return st.team.filter(p=>p.active).map(p=>{
   const entries=st.timeclock.entries.filter(x=>x.person===p.id&&x.date>=from&&x.date<=to),done=entries.reduce((n,x)=>n+P.counted(st,x,now),0);
   const ahead=st.shifts.filter(x=>x.person===p.id&&x.date>=from&&x.date<=to&&!S.absence(st,x)&&!entries.some(y=>y.shiftId===x.id)&&P.shiftTimes(x).start>now).reduce((n,x)=>n+S.metrics(st,x).scheduledMinutes,0);
   const total=done+ahead,ot=Math.max(0,total-c.weeklyOvertime*60),rate=st.scheduling.defaults[p.id]?.rate||0;
   return {p,done,ahead,total,ot,cost:ot/60*rate*c.multiplier};
  }).sort((a,b)=>b.total-a.total);
 }

 // The daily close: the manager's end-of-day report. Sales, guests, comps and cash are entered; everything else
 // about the day is already in Brigly and filled in.
 function daySummary(st,date){
  const now=P.stamp(),shifts=st.shifts.filter(x=>x.date===date),entries=st.timeclock.entries.filter(x=>x.date===date);
  const clockedMin=entries.reduce((n,x)=>n+P.counted(st,x,now),0),clockedCost=entries.reduce((n,x)=>n+P.counted(st,x,now)/60*(st.shifts.find(y=>y.id===x.shiftId)?.payRate??st.scheduling.defaults[x.person]?.rate??0),0);
  const rosterMin=shifts.reduce((n,x)=>n+S.metrics(st,x).workMinutes,0),roster=shifts.reduce((n,x)=>n+S.metrics(st,x).wages,0),useClock=entries.length>0;
  let rows=[];try{rows=(B.work?.history?B.work.history(st,date,date,'','',{}):[]).flatMap(g=>g.rows).filter(r=>!r.removed);}catch{}
  const res=st.reservations.filter(r=>r.date===date),late=shifts.filter(x=>{const en=entries.find(y=>y.shiftId===x.id);return en?P.flags(st,en).some(f=>f.kind==='late'):!!S.metrics(st,x).late;}).length;
  const received=st.orders.filter(o=>o.status==='Received'&&(o.receivedAt||'').slice(0,10)===date);
  return {services:[...new Set(shifts.map(x=>x.service))],laborMin:useClock?clockedMin:rosterMin,labor:(useClock?clockedCost:roster)*(1+P.settings(st).employerTax/100),useClock,team:new Set(shifts.map(x=>x.person)).size,
   tasks:rows.length,done:rows.filter(r=>r.check).length,alerts:st.unavailable.filter(u=>u.date===date&&u.status!=='Declined'),covers:res.filter(r=>!['Cancelled','No-show'].includes(r.status)).reduce((n,r)=>n+r.guests,0),noShows:res.filter(r=>r.status==='No-show').length,
   late,sick:shifts.filter(x=>S.absence(st,x)?.kind==='sick').length,deliveries:received.reduce((n,o)=>n+(o.receivedQty??o.quantity)*(o.cost||0),0),records:(st.writeups||[]).filter(w=>w.date===date&&w.status!=='Draft').length,kudos:st.business.kudos.filter(k=>k.at.slice(0,10)===date).length,notes:(st.shiftNotes||[]).filter(n=>n.date===date&&!n.archived).length};
 }
 const dayFacts=(st,date,d)=>[['Labor',`${whole(d.labor)} · ${hrs(d.laborMin)} h ${d.useClock?'clocked':'scheduled'}`],['Team on shift',plural(d.team,'person')],['Checklists',d.tasks?`${Math.round(d.done/d.tasks*100)}% · ${d.done} of ${d.tasks} tasks`:'No lists'],['86’d',d.alerts.length?d.alerts.map(a=>a.name).join(', '):'Nothing'],['Reservations',`${d.covers} covers${d.noShows?' · '+plural(d.noShows,'no-show'):''}`],['Attendance',d.late||d.sick?[d.late?d.late+' late':'',d.sick?d.sick+' sick':''].filter(Boolean).join(' · '):'Everyone on time'],['Deliveries',d.deliveries?whole(d.deliveries)+' received':'None'],['Shift notes',d.notes?plural(d.notes,'note'):'None']];
 function daily(){
  const st=s(),Z=B.biz,t=today(),open=Z.openDays(st,B.addDays(t,-14),t),days=Array.from({length:14},(_,i)=>B.addDays(t,-13+i));
  const closes=st.business.closes,last=Object.keys(closes).sort().reverse().slice(0,10);
  const strip=`<div class="dc-strip">${days.map(d=>{const c=closes[d],ran=st.shifts.some(x=>x.date===d),isOpen=open.includes(d);return `<button type="button" class="dc-day ${c?'is-closed':isOpen?'is-open':''}" data-action="fin-close" data-id="${d}" ${!ran?'disabled':''} aria-label="${dateLabel(d,{weekday:'long',month:'long',day:'numeric'})}: ${c?'closed':isOpen?'not closed':'no service'}"><small>${dateLabel(d,{weekday:'short'})}</small><strong>${dateLabel(d,{day:'numeric'})}</strong><i>${c?'✓':isOpen?'!':''}</i></button>`;}).join('')}</div>`;
  const next=open[0],d=next&&daySummary(st,next),preset=next&&st.business.sales.filter(x=>x.date===next).reduce((n,x)=>n+x.amount,0);
  const hero=next?`<section class="panel mg-panel dc-hero"><div class="dc-hero-head"><div><p class="eyebrow">READY TO CLOSE</p><h3>${dateLabel(next,{weekday:'long',month:'long',day:'numeric'})}</h3><p>${d.services.join(' and ')} · Brigly has filled in everything it already knows. Add sales, guests, comps and cash from your POS.</p></div>${act('Close out the day','close',next,'')}</div><dl class="dc-facts">${dayFacts(st,next,d).map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>${preset?`<p class="fin-note">${whole(preset)} in sales is already recorded for this day. Check it against your POS.</p>`:''}</section>`:`<section class="panel mg-panel"><div class="empty"><strong>Every day is closed</strong>The next close-out appears here after tonight’s service.</div></section>`;
  const rows=last.map(dt=>{const c=closes[dt],pl=Z.pnl(st,dt,dt);return `<tr class="report-row-link" data-action="fin-close" data-id="${dt}"><td><strong>${dateLabel(dt,{weekday:'short',month:'short',day:'numeric'})}</strong></td><td><strong>${whole(c.sales)}</strong></td><td>${c.guests}</td><td>${c.guests?money(c.sales/c.guests):'—'}</td><td>${badge(pl.laborPct+'%',pl.laborPct<=30?'tone-sage':pl.laborPct<=35?'tone-amber':'tone-danger')}</td><td>${c.sales?Math.round(c.comps/c.sales*1000)/10:0}%</td><td>${c.cash?(c.cash>0?'+':'')+money(c.cash):'Even'}</td><td>${e(name(c.closedBy))}${c.notes?'<small class="table-detail">'+e(c.notes.slice(0,60))+(c.notes.length>60?'…':'')+'</small>':''}</td></tr>`;}).join('');
  const table=`<section class="panel mg-panel"><div class="panel-head"><div><h3>Recent closes</h3><p>Open any day to see or correct it</p></div>${button('Sales report ›','mg-tab','sales','','secondary small')}</div><div class="table-scroll"><table><thead><tr><th>DAY</th><th>NET SALES</th><th>GUESTS</th><th>AVG CHECK</th><th>LABOR %</th><th>COMPS</th><th>CASH</th><th>CLOSED BY</th></tr></thead><tbody>${rows||'<tr><td colspan="8">No closed days yet.</td></tr>'}</tbody></table></div></section>`;
  return strip+hero+table;
 }
 function closeForm(date){
  // The POS fills in each service's net sales when nothing was entered by hand yet.
  const st=s(),c=st.business.closes[date],d=daySummary(st,date),pos=B.pos&&st.pos?B.pos.daySales(st,date):{},services=[...new Set([...d.services,...st.business.sales.filter(x=>x.date===date).map(x=>x.service),...Object.keys(pos)])];
  const amount=v=>st.business.sales.find(x=>x.date===date&&x.service===v)?.amount??(pos[v]!==undefined?pos[v].toFixed(2):'');
  return `${c?`<p class="fin-note">Closed by ${e(name(c.closedBy))} on ${new Date(c.closedAt).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}. Saving updates it.</p>`:''}<dl class="dc-facts is-compact">${dayFacts(st,date,d).map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><fieldset class="mg-form-section"><legend>From your POS</legend>${Object.keys(pos).length?`<p class="fin-note">Brigly POS recorded ${Object.entries(pos).map(([k,v])=>whole(v)+' for '+e(k)).join(' and ')}. The fields below start from those totals.</p>`:''}<div class="mg-form-grid">${services.map(v=>`<label>Net sales · ${e(v)}<input type="number" name="sales_${e(v)}" min="0" step="0.01" required value="${amount(v)}" placeholder="0.00"></label>`).join('')}${st.specials.filter(x=>x.date===date&&x.active).length?'</div></fieldset><fieldset class="mg-form-section"><legend>Specials and happenings sold</legend><div class="mg-form-grid">'+st.specials.filter(x=>x.date===date&&x.active).map(x=>`<label>${e(x.name)} · units<input type="number" name="sold_${e(x.id)}" min="0" step="1" value="${c?.specials?.[x.id]??''}" placeholder="From the POS item report"></label>`).join('')+'</div></fieldset><fieldset class="mg-form-section"><legend>Guests, comps and cash</legend><div class="mg-form-grid">':''}<label>Guests · ${d.covers} reserved<input type="number" name="guests" min="0" step="1" required value="${c?.guests??d.covers}"></label><label>Comps and discounts ($)<input type="number" name="comps" min="0" step="0.01" value="${c?.comps??''}" placeholder="0.00"></label><label>Cash over or short ($)<input type="number" name="cash" step="0.01" value="${c?.cash??''}" placeholder="0.00 · use minus for short"></label></div></fieldset><label>Manager’s notes for the day<textarea name="notes" maxlength="3000" placeholder="Anything the next manager or the owner should know: guest issues, equipment, staffing, what went well">${e(c?.notes||'')}</textarea></label><p class="fin-note">Net sales are after discounts and comps, before sales tax and tips.</p>`;
 }
 // Stock money: what sits on the shelves, what was bought and used, what is owed back and what is already committed.
 function inventory(){
  const st=s(),t=today(),from=B.addDays(t,-27),items=st.stock.items.filter(i=>i.active!==false),vendor=id=>st.stock.vendors.find(v=>v.id===id)?.name||'Made in house',itemOf=id=>st.stock.items.find(i=>i.id===id);
  const day=o=>(o.receivedAt||'').slice(0,10),got=o=>o.receivedQty??o.quantity,received=st.orders.filter(o=>o.status==='Received');
  const recent=received.filter(o=>day(o)>=from&&day(o)<=t),spend=recent.reduce((n,o)=>n+got(o)*(o.cost||0),0),sales=B.biz?B.biz.pnl(st,from,t).sales:0;
  const value=items.reduce((n,i)=>n+(i.onHand||0)*i.cost,0),counted=items.filter(i=>i.onHand!==null),lastCount=st.stock.counts.filter(c=>c.status==='Submitted').sort((a,b)=>b.submittedAt.localeCompare(a.submittedAt))[0];
  const usage=st.stock.counts.filter(c=>c.status==='Submitted'&&c.submittedAt.slice(0,10)>=from).reduce((n,c)=>n+Object.entries(c.entries).reduce((m,[id,x])=>m+(x.used>0?x.used*(itemOf(id)?.cost||0):0),0),0);
  const open=st.orders.filter(o=>['Approved','Ordered'].includes(o.status)),committed=open.reduce((n,o)=>n+o.quantity*(o.cost||0),0);
  const shorts=received.filter(o=>day(o)>=B.addDays(t,-30)&&got(o)<o.quantity),credits=shorts.reduce((n,o)=>n+(o.quantity-got(o))*(o.cost||0),0);
  const kpis=`<div class="mg-kpis">${kpi('ON HAND',whole(value),'',`${counted.length} of ${items.length} items counted${lastCount?' · last count '+dateLabel(lastCount.submittedAt.slice(0,10)):''}`)}${kpi('PURCHASES · 4 WEEKS',whole(spend),'',sales?`${Math.round(spend/sales*1000)/10}% of ${whole(sales)} sales`:'Deliveries received')}${kpi('USED · 4 WEEKS',whole(usage),'','From stock counts: counted drop since the last count')}${kpi('ON ORDER',whole(committed),'',`${plural(open.length,'line')} approved or ordered`)}${kpi('CREDITS TO CLAIM',whole(credits),'',shorts.length?`${plural(shorts.length,'short delivery','short deliveries')} in 30 days`:'No short deliveries')}</div>`;
  const wk=B.monday(t),weekly=Array.from({length:12},(_,i)=>{const a=B.addDays(wk,(i-11)*7),b=B.addDays(a,6),v=received.filter(o=>day(o)>=a&&day(o)<=b).reduce((n,o)=>n+got(o)*(o.cost||0),0);return {label:dateLabel(a,{month:'numeric',day:'numeric'}),value:Math.round(v),current:i===11,tip:`Week of ${dateLabel(a)} · ${whole(v)} received`};});
  const roll=(list,key,val)=>[...list.reduce((m,x)=>{const k=key(x);m.set(k,(m.get(k)||0)+val(x));return m;},new Map())].map(([label,v])=>({label,value:Math.round(v),tip:label+' · '+whole(v)})).sort((a,b)=>b.value-a.value);
  const chart=`<section class="panel mg-panel"><div class="panel-head"><div><h3>Purchases by week</h3><p>Deliveries received, last 12 weeks</p></div>${button('Order sheet ›','stock-go','orders','data-stage="order"','secondary small')}</div><div class="fin-chart-wrap">${bars(weekly,whole,'Purchases by week')}</div></section>`;
  const vendors=`<section class="panel mg-panel"><div class="panel-head"><div><h3>Spend by vendor · 4 weeks</h3><p>${whole(spend)} across ${new Set(recent.map(o=>o.vendor)).size} vendors</p></div></div><div class="mg-mix-body"><div class="mg-mix">${hbars(roll(recent,o=>vendor(o.vendor),o=>got(o)*(o.cost||0)).slice(0,8),whole)}</div></div></section>`;
  const shelf=`<section class="panel mg-panel"><div class="panel-head"><div><h3>On the shelves</h3><p>Value on hand by category, at current cost</p></div>${button('Open Stock','navigate','stock','','secondary small')}</div><div class="mg-mix-body"><div class="mg-mix">${hbars(roll(items.filter(i=>i.onHand),i=>i.category,i=>i.onHand*i.cost).slice(0,10),whole)}</div></div></section>`;
  // Price watch: the latest price paid against what the item cost six weeks ago or more.
  const watch=[...new Set(received.map(o=>o.item).filter(Boolean))].map(id=>{const mine=received.filter(o=>o.item===id).sort((a,b)=>day(a).localeCompare(day(b))),old=mine.filter(o=>day(o)<B.addDays(t,-42)),now=mine.at(-1);if(!old.length||!now)return null;const was=old.at(-1).cost||0,is=now.cost||0;if(!was||Math.abs(is-was)<0.005)return null;const qty=mine.filter(o=>day(o)>=B.addDays(t,-30)).reduce((n,o)=>n+got(o),0);return {item:itemOf(id),was,is,pct:Math.round((is-was)/was*1000)/10,impact:qty*(is-was),vendor:vendor(now.vendor)};}).filter(Boolean).sort((a,b)=>Math.abs(b.impact)-Math.abs(a.impact));
  const prices=`<section class="panel mg-panel"><div class="panel-head"><div><h3>Price watch</h3><p>Latest price paid against six or more weeks ago, and what it adds per month at current volume</p></div></div>${watch.length?`<div class="table-scroll"><table><thead><tr><th>ITEM</th><th>VENDOR</th><th>WAS</th><th>NOW</th><th>CHANGE</th><th>PER MONTH</th></tr></thead><tbody>${watch.slice(0,10).map(x=>`<tr><td><strong>${e(x.item?.name||'Item')}</strong><small class="table-detail">per ${e(x.item?.unit||'unit')}</small></td><td>${e(x.vendor)}</td><td>${money(x.was)}</td><td><strong>${money(x.is)}</strong></td><td>${badge((x.pct>0?'+':'')+x.pct+'%',x.pct>0?'tone-danger':'tone-sage')}</td><td>${x.impact>0?'+':''}${money(x.impact)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Prices are steady</strong>No item costs more or less than it did six weeks ago.</div>'}</section>`;
  const credit=shorts.length?`<section class="panel mg-panel"><div class="panel-head"><div><h3>Credits to claim · ${whole(credits)}</h3><p>Deliveries that arrived short in the last 30 days. Ask each vendor for a credit on the next invoice.</p></div></div><div class="table-scroll"><table><thead><tr><th>DELIVERED</th><th>VENDOR</th><th>ITEM</th><th>ORDERED</th><th>RECEIVED</th><th>CREDIT</th></tr></thead><tbody>${shorts.sort((a,b)=>day(b).localeCompare(day(a))).map(o=>`<tr><td>${dateLabel(day(o))}${o.po?`<small class="table-detail">${e(o.po)}</small>`:''}</td><td>${e(vendor(o.vendor))}</td><td><strong>${e(o.name)}</strong></td><td>${o.quantity} ${e(o.unit)}</td><td>${got(o)} ${e(o.unit)}</td><td><strong>${money((o.quantity-got(o))*(o.cost||0))}</strong></td></tr>`).join('')}</tbody></table></div></section>`:'';
  const byVendor=roll(open,o=>vendor(o.vendor),o=>o.quantity*(o.cost||0));
  const orders=open.length?`<section class="panel mg-panel"><div class="panel-head"><div><h3>On order · ${whole(committed)}</h3><p>Approved or placed and not yet received</p></div>${button('Order sheet','stock-go','orders','data-stage="order"','secondary small')}</div><div class="hr-leave-list">${byVendor.map(v=>{const lines=open.filter(o=>vendor(o.vendor)===v.label),placed=lines.filter(o=>o.status==='Ordered');return `<div><span><strong>${e(v.label)}</strong><small class="table-detail">${plural(lines.length,'line')} · ${placed.length?placed.length+' placed'+(placed[0].expected?' · arrives '+dateLabel(placed[0].expected):''):'not placed yet'}</small></span><strong>${whole(v.value)}</strong></div>`;}).join('')}</div></section>`:'';
  const top=[...recent.reduce((m,o)=>{const k=o.item||o.name,x=m.get(k)||{name:o.name,unit:o.unit,vendor:vendor(o.vendor),qty:0,spend:0,lines:0};x.qty+=got(o);x.spend+=got(o)*(o.cost||0);x.lines++;return m.set(k,x);},new Map()).values()].sort((a,b)=>b.spend-a.spend).slice(0,10);
  const topTable=top.length?`<section class="panel mg-panel"><div class="panel-head"><div><h3>Top items by spend · 4 weeks</h3><p>What drives the purchasing bill. Check these against par levels and menu prices.</p></div></div><div class="table-scroll"><table><thead><tr><th>ITEM</th><th>VENDOR</th><th>BOUGHT</th><th>DELIVERIES</th><th>SPEND</th><th>SHARE</th></tr></thead><tbody>${top.map(x=>`<tr><td><strong>${e(x.name)}</strong></td><td>${e(x.vendor)}</td><td>${Math.round(x.qty*10)/10} ${e(x.unit)}</td><td>${x.lines}</td><td><strong>${whole(x.spend)}</strong></td><td>${spend?Math.round(x.spend/spend*100):0}%</td></tr>`).join('')}</tbody></table></div></section>`:'';
  return kpis+`<div class="mg-grid">${chart}${vendors}</div><div class="mg-grid">${prices}${shelf}</div>`+topTable+credit+orders;
 }
 function overtimeWatch(){
  const st=s(),c=P.settings(st),watch=projection(st).filter(x=>x.total>=(c.weeklyOvertime-6)*60).slice(0,8);
  return `<section class="panel mg-panel"><div class="panel-head"><div><h3>Overtime watch · this week</h3><p>Clocked so far plus what is still scheduled, against ${c.weeklyOvertime} hours</p></div>${button('Open Scheduling','app-screen','shifts','','secondary small')}</div>${watch.length?`<div class="fin-watch">${watch.map(x=>`<div class="fin-watch-row"><div class="crew-name">${avatar(x.p)}<div>${e(x.p.name)}<small>${hrs(x.done)} h worked · ${hrs(x.ahead)} h scheduled</small></div></div><div class="fin-meter" style="--limit:${c.weeklyOvertime/Math.max(c.weeklyOvertime+8,x.total/60)*100}%"><i style="width:${Math.min(100,x.total/60/Math.max(c.weeklyOvertime+8,x.total/60)*100)}%" data-over="${x.ot>0}"></i></div><div class="fin-watch-total"><strong>${hrs(x.total)} h</strong>${x.ot?badge(`${hrs(x.ot)} h OT · ${whole(x.cost)}`,'tone-amber'):badge('Under '+c.weeklyOvertime+' h','tone-sage')}</div></div>`).join('')}</div>`:'<div class="empty"><strong>No overtime coming</strong>Nobody is within 6 hours of the weekly limit.</div>'}</section>`;
 }
 function laborSplit(from,to){
  const st=s(),by=key=>{const m=new Map();for(const x of st.shifts.filter(x=>x.date>=from&&x.date<=to)){const k=key(x);if(!k)continue;const row=m.get(k)||{label:k,value:0,mins:0};row.value+=S.metrics(st,x).wages;row.mins+=S.metrics(st,x).workMinutes;m.set(k,row);}return [...m.values()].sort((a,b)=>b.value-a.value).map(r=>({...r,tip:`${r.label} · ${whole(r.value)} · ${hrs(r.mins)} hrs`}));};
  return `<section class="panel mg-panel"><div class="panel-head"><div><h3>Where labor goes</h3><p>Wages by station and role, ${range(from,to)}</p></div></div><div class="mg-mix-body"><div class="mg-mix"><h4>By station</h4>${hbars(by(x=>x.area),whole)}</div><div class="mg-mix"><h4>By role</h4>${hbars(by(x=>B.person(x.person)?.role),whole)}</div></div></section>`;
 }
 function timesheets(){
  const st=s(),f=focus(st);if(!tsFrom)tsFrom=f.from;
  const p=P.period(st,tsFrom),run=P.runFor(st,p.from),now=P.stamp(),entries=st.timeclock.entries.filter(x=>x.date>=p.from&&x.date<=p.to);
  const miss=P.missing(st,p.from,p.to),c=P.calc(st,p.from,p.to),pending=entries.filter(x=>x.out&&x.status!=='Approved'),open=st.timeclock.entries.filter(x=>!x.out);
  const issues=entries.reduce((n,x)=>n+P.flags(st,x,now).filter(f=>['danger','amber'].includes(f.tone)).length,0)+miss.length,sched=rosterMinutes(st,p.from,p.to<today()?p.to:today());
  const nav=`<div class="fin-period"><button type="button" class="button secondary small" data-action="fin-ts-period" data-id="-1" aria-label="Previous pay period">‹</button><strong>${range(p.from,p.to)}</strong><button type="button" class="button secondary small" data-action="fin-ts-period" data-id="1" aria-label="Next pay period" ${p.from>=P.period(st,today()).from?'disabled':''}>›</button>${p.from===f.from?badge(run?'Pay run '+run.status.toLowerCase():'Next payroll','tone-orange'):p.from===P.period(st,today()).from?badge('Current period'):''}</div>`;
  const kpis=`<div class="res-kpis">${kpi('WORKED',hrs(c.totals.minutes+entries.filter(x=>!x.out).reduce((n,x)=>n+P.counted(st,x,now),0)),'hrs',`${hrs(sched)} hrs scheduled to date`)}${kpi('OVERTIME',hrs(c.totals.otMinutes),'hrs',c.totals.otMinutes?whole(c.totals.overtimePay)+' overtime pay':'None so far')}${kpi('TO APPROVE',pending.length,'entries',run?'Hours are locked in an approved pay run':pending.length?'Approve before payroll':'All approved')}${kpi('EXCEPTIONS',issues,'',`${miss.length} without a clock-in · ${entries.filter(x=>P.flags(st,x,now).some(f=>f.kind==='noout')).length} missing clock-outs`)}</div>`;
  const live=open.filter(x=>!P.flags(st,x,now).some(f=>f.kind==='noout'));
  const onClock=live.length?`<section class="fin-live"><h3><span class="fin-dot"></span>On the clock now · ${live.length}</h3><div class="mg-chips">${live.map(x=>`<span class="fin-live-chip">${avatar(B.person(x.person))}<span><strong>${e(name(x.person))}</strong><small>${P.onBreak(x)?'On break':'Since '+clock(x.in)} · ${span(P.worked(x,now))}</small></span></span>`).join('')}</div></section>`:'';
  const lockNote=run?`<div class="fin-note">This pay period is in an approved pay run, so its hours are locked. ${act('Open pay run','go-runs','','secondary small')}</div>`:'';
  const people=[...new Set([...entries.map(x=>x.person),...miss.map(x=>x.person)])].map(id=>s().team.find(q=>q.id===id)).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name));
  const cards=people.map(q=>{
   const mine=entries.filter(x=>x.person===q.id).sort((a,b)=>a.in.localeCompare(b.in)),gaps=miss.filter(x=>x.person===q.id),line=c.lines.find(l=>l.person===q.id);
   const rows=[...mine.map(x=>({date:x.date,at:x.in,entry:x})),...gaps.map(x=>({date:x.date,at:x.date+'T'+x.start,gap:x}))].sort((a,b)=>a.at.localeCompare(b.at));
   const flagged=mine.reduce((n,x)=>n+P.flags(st,x,now).filter(f=>['danger','amber'].includes(f.tone)).length,0)+gaps.length,waiting=mine.filter(x=>x.out&&x.status!=='Approved').length;
   const body=rows.map(r=>{
    if(r.gap){const x=r.gap;return `<tr class="fin-gap"><td><strong>${dateLabel(x.date,{weekday:'short',month:'short',day:'numeric'})}</strong><small class="table-detail">${e(x.service)} · ${e(x.area)}</small></td><td>${x.start}–${x.end}</td><td colspan="4">${badge('No clock-in','tone-danger')} <span class="table-detail">No absence reported</span></td><td></td><td>${run?'':act('Add time','add',x.id,'secondary small',`data-person="${e(x.person)}"`)}</td></tr>`;}
    const x=r.entry,sh=st.shifts.find(y=>y.id===x.shiftId),fl=P.flags(st,x,now),brk=typeof x.breakMinutes==='number'?x.breakMinutes:(x.breaks||[]).reduce((n,b)=>n+(b.end?P.between(b.start,b.end):0),0);
    return `<tr><td><strong>${dateLabel(x.date,{weekday:'short',month:'short',day:'numeric'})}</strong><small class="table-detail">${sh?e(sh.service)+' · '+e(sh.area):'Unscheduled'}</small></td><td>${sh?sh.start+'–'+sh.end:'—'}</td><td>${clock(x.in)}</td><td>${x.out?clock(x.out):'<span class="table-detail">—</span>'}</td><td>${brk?brk+' min':'—'}</td><td><strong>${x.out||!fl.some(f=>f.kind==='noout')?span(P.worked(x,now)):'—'}</strong></td><td><div class="mg-chips">${fl.map(f=>badge(f.label,'tone-'+f.tone)).join('')}${x.status==='Approved'?badge('Approved','tone-sage'):x.out?badge('To approve'):badge(fl.some(f=>f.kind==='noout')?'Open':'On the clock')}</div></td><td><div class="row-actions">${run?'':(x.out&&x.status!=='Approved'?act('Approve','approve',x.id,'secondary small'):'')+act(fl.some(f=>f.kind==='noout')?'Fix clock-out':'Edit','edit',x.id,fl.some(f=>f.kind==='noout')?'small':'quiet small')}</div></td></tr>`;
   }).join('');
   return `<details class="fin-person" ${flagged||waiting?'open':''} data-key="ts-${e(q.id)}"><summary><div class="crew-name">${avatar(q)}<div>${e(q.name)}<small>${e(q.role)} · ${e(q.area)}</small></div></div><div class="fin-person-meta"><span><strong>${hrs(line?.minutes||0)} h</strong> worked</span>${line?.otMinutes?badge(hrs(line.otMinutes)+' h overtime','tone-amber'):''}${flagged?badge(plural(flagged,'exception'),'tone-danger'):''}${waiting?badge(waiting+' to approve'):mine.length?badge('Approved','tone-sage'):''}<span class="fin-person-pay">${money(line?.gross||0)}</span></div></summary><div class="table-scroll"><table><thead><tr><th>DAY</th><th>SCHEDULED</th><th>IN</th><th>OUT</th><th>BREAK</th><th>WORKED</th><th>NOTES</th><th></th></tr></thead><tbody>${body}</tbody></table></div></details>`;
  }).join('');
  const tools=`<div class="fin-toolbar">${nav}<div class="toolbar">${!run&&pending.length?act(`Approve all ${pending.length}`,'approve-all',p.from,''):''}</div></div>`;
  return tools+kpis+onClock+lockNote+(cards||'<div class="panel"><div class="empty"><strong>No time recorded</strong>Clock-ins for this pay period will appear here.</div></div>');
 }

 const stepNames=['Approve hours','Approve pay run','Export to payroll','Mark paid'];
 function payruns(){
  const st=s(),c=P.settings(st),f=focus(st),run=f.run,data=run||P.calc(st,f.from,f.to),t=data.totals,ready=P.readiness(st,f.from,f.to);
  const step=run?{Approved:2,Exported:3,Paid:4}[run.status]:ready.pending.length||ready.open.length||!f.ended?0:1;
  const days=Math.round((new Date(f.payDate+'T12:00:00')-new Date(today()+'T12:00:00'))/864e5);
  const stepper=`<ol class="fin-steps">${stepNames.map((n,i)=>`<li class="${i<step?'done':i===step?'now':''}"><span>${i<step?'✓':i+1}</span>${n}</li>`).join('')}</ol>`;
  const primary=run?(run.status==='Approved'?act('Export for '+c.provider,'export',run.id,'')+act('Reopen','reopen',run.id,'quiet'):run.status==='Exported'?act('Mark as paid','paid',run.id,'')+act('Download again','download',run.id,'quiet'):act('Download','download',run.id,'secondary')):!f.ended?`<p class="fin-note-inline">The period ends ${dateLabel(f.to,{weekday:'short',month:'short',day:'numeric'})}. Approve it after that.</p>`:ready.open.length?`<p class="fin-note-inline">${plural(ready.open.length,'person')} still clocked in. Fix their clock-out first.</p>${act('Open timesheets','go-ts',f.from,'secondary')}`:act(ready.pending.length?'Approve hours & pay run':'Approve pay run','approve-run',f.from,'');
  const check=(ok,warn,label,detail,action='')=>`<li class="${ok?'ok':warn?'warn':'stop'}"><span>${ok?'✓':'!'}</span><div><strong>${label}</strong><small>${detail}</small></div>${ok?'':action}</li>`;
  const checks=run?'':`<ul class="fin-checks">${check(!ready.pending.length,true,'Timesheets approved',ready.pending.length?`${plural(ready.pending.length,'entry')} to approve. Approving the pay run approves them too.`:'Every entry is approved.',act('Review','go-ts',f.from,'secondary small'))}${check(!ready.open.length,false,'Everyone clocked out',ready.open.length?ready.open.map(x=>name(x.person)).join(', ')+' still clocked in':'No open entries.',act('Fix','go-ts',f.from,'secondary small'))}${check(!ready.missing.length,true,'Scheduled shifts have time',ready.missing.length?`${plural(ready.missing.length,'shift')} with no clock-in. Add time if they worked.`:'Every shift that was worked has a clock-in.',act('Review','go-ts',f.from,'secondary small'))}${check(!ready.payment.length,true,'Payment details on file',ready.payment.length?ready.payment.map(p=>p.name).join(', '):'Everyone being paid has a payment method.',button('HR files','mg-tab','people','','secondary small'))}${check(!ready.w4.length,true,'W-4 on file',ready.w4.length?ready.w4.map(p=>p.name).join(', '):'Everyone being paid has a W-4.',button('Compliance','mg-tab','compliance','','secondary small'))}</ul>`;
  const hero=`<section class="panel fin-run"><div class="fin-run-head"><div><p class="eyebrow">${run?'PAY RUN':f.ended?'NEXT PAYROLL':'CURRENT PAY PERIOD'}</p><h3>${range(f.from,f.to)}</h3><p>Pay date ${dateLabel(f.payDate,{weekday:'short',month:'short',day:'numeric'})}${days>=0?` · in ${plural(days,'day')}`:` · ${plural(-days,'day')} ago`} · ${c.frequency==='weekly'?'weekly':'every two weeks'}</p></div><div class="fin-run-actions">${primary}</div></div>${stepper}<div class="fin-tiles"><div><small>People</small><strong>${t.people}</strong></div><div><small>Hours</small><strong>${hrs(t.minutes)}</strong><em>${hrs(t.otMinutes)} overtime</em></div><div><small>Gross pay</small><strong>${money(t.gross)}</strong><em>${money(t.overtimePay)} overtime pay</em></div><div><small>Employer taxes · est.</small><strong>${money(t.employerTax)}</strong><em>${c.employerTax}% of gross</em></div><div class="is-total"><small>Total labor cost</small><strong>${money(t.cost)}</strong><em>${money(t.tips)} tips declared, paid by guests</em></div></div>${checks}</section>`;
  const lines=`<section class="panel mg-panel"><div class="panel-head"><div><h3>${run?'Pay run lines':'Preview · from clocked hours'}</h3><p>${run?'Locked when the pay run was approved':'Updates as timesheets change'} · overtime after ${c.weeklyOvertime} h a week${c.dailyOvertime?` or ${c.dailyOvertime} h a day`:''} at ${c.multiplier}×</p></div></div>${linesTable(data)}</section>`;
  const runs=st.payroll.runs.slice().sort((a,b)=>b.from.localeCompare(a.from));
  const history=`<section class="panel mg-panel"><div class="panel-head"><div><h3>Pay run history</h3><p>Gross pay per run · ${runs.length} runs on record</p></div></div><div class="table-scroll"><table><thead><tr><th>PAY PERIOD</th><th>PAY DATE</th><th>PEOPLE</th><th>HOURS</th><th>GROSS PAY</th><th>TOTAL COST</th><th>STATUS</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr class="report-row-link" data-action="fin-run" data-id="${e(r.id)}"><td><strong>${range(r.from,r.to)}</strong></td><td>${dateLabel(r.payDate,{weekday:'short',month:'short',day:'numeric'})}</td><td>${r.totals.people}</td><td>${hrs(r.totals.minutes)}</td><td><strong>${money(r.totals.gross)}</strong></td><td>${money(r.totals.cost)}</td><td>${badge(r.status,r.status==='Paid'?'tone-sage':'tone-orange')}</td><td>${act('View','run',r.id,'secondary small')}</td></tr>`).join('')||'<tr><td colspan="8">No pay runs yet.</td></tr>'}</tbody></table></div></section>`;
  return hero+lines+history;
 }
 function linesTable(data){
  const st=s();
  return `<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>REGULAR</th><th>OVERTIME</th><th>PAID LEAVE</th><th>RATE</th><th>OVERTIME PAY</th><th>GROSS</th><th>TIPS</th></tr></thead><tbody>${data.lines.map(l=>{const p=st.team.find(x=>x.id===l.person);return `<tr><td><strong>${e(name(l.person))}</strong><small class="table-detail">${e([p?.hr?.employeeId,p?.hr?.payMethod||'Payment method not set'].filter(Boolean).join(' · '))}</small></td><td>${hrs(l.regMinutes)} h</td><td>${l.otMinutes?hrs(l.otMinutes)+' h':'—'}</td><td>${l.leaveMinutes?hrs(l.leaveMinutes)+' h · '+money(l.leavePay):'—'}</td><td>${money(l.rate)}</td><td>${l.overtimePay?money(l.overtimePay):'—'}</td><td><strong>${money(l.gross)}</strong></td><td>${l.tips?money(l.tips):'—'}</td></tr>`;}).join('')||'<tr><td colspan="8">No hours in this period.</td></tr>'}</tbody><tfoot><tr><td><strong>Total</strong></td><td>${hrs(data.totals.minutes-data.totals.otMinutes)} h</td><td>${hrs(data.totals.otMinutes)} h</td><td>${hrs(data.totals.leaveMinutes)} h</td><td></td><td>${money(data.totals.overtimePay)}</td><td><strong>${money(data.totals.gross)}</strong></td><td>${money(data.totals.tips)}</td></tr></tfoot></table></div>`;
 }
 function exportRun(r){
  const st=s(),c=P.settings(st),cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
  const rows=[['Employee ID','Employee','Pay period start','Pay period end','Pay date','Regular hours','Overtime hours','Paid leave hours','Average rate','Regular pay','Overtime pay','Leave pay','Gross pay','Declared tips','Payment method','Work state'],...r.lines.map(l=>{const p=st.team.find(x=>x.id===l.person);return [p?.hr?.employeeId||'',name(l.person),r.from,r.to,r.payDate,(l.regMinutes/60).toFixed(2),(l.otMinutes/60).toFixed(2),(l.leaveMinutes/60).toFixed(2),l.rate,l.regularPay,l.overtimePay,l.leavePay,l.gross,l.tips,p?.hr?.payMethod||'',p?.hr?.workState||''];})];
  const blob=new Blob(['﻿'+rows.map(x=>x.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download=`brigly-payroll-${r.from}-${r.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  return c.provider;
 }

 // The crew's own pay: this period so far, their timesheet and their stubs.
 function myPay(){
  const st=s(),id=me(),now=P.stamp(),cur=P.period(st,today()),line=P.calc(st,cur.from,today()).lines.find(l=>l.person===id),mine=st.timeclock.entries.filter(x=>x.person===id&&x.date>=cur.from&&x.date<=cur.to).sort((a,b)=>b.in.localeCompare(a.in));
  const stubs=st.payroll.runs.filter(r=>r.lines.some(l=>l.person===id)).sort((a,b)=>b.from.localeCompare(a.from)),last=stubs[0]?.lines.find(l=>l.person===id);
  return `<section class="panel mg-panel fin-mypay"><div class="panel-head"><div><h2>My pay</h2><p>Pay period ${range(cur.from,cur.to)} · paid ${dateLabel(cur.payDate,{weekday:'short',month:'short',day:'numeric'})}</p></div></div><div class="fin-tiles"><div><small>Clocked this period</small><strong>${hrs(mine.reduce((n,x)=>n+P.counted(st,x,now),0))} h</strong><em>${mine.filter(x=>x.status==='Approved').length} of ${mine.length} entries approved</em></div><div><small>Gross so far · est.</small><strong>${money(line?.gross||0)}</strong><em>Before taxes and deductions</em></div>${B.biz?(()=>{const sick=B.biz.balance(st,id,'sick'),pto=B.biz.balance(st,id,'pto');return `<div><small>Sick leave</small><strong>${sick.eligible?hrs(sick.balance*60)+' h':'—'}</strong><em>${sick.eligible?hrs(sick.accrued*60)+' h earned this year':''}</em></div><div><small>Paid time off</small><strong>${pto.eligible?hrs(pto.balance*60)+' h':'—'}</strong><em>${pto.eligible?hrs(pto.accrued*60)+' h earned this year':'Not part of your contract'}</em></div>`;})():''}<div><small>Last paycheck · gross</small><strong>${last?money(last.gross):'—'}</strong><em>${stubs[0]?'Paid '+dateLabel(stubs[0].payDate):'No pay stubs yet'}</em></div></div>${mine.length?`<details class="fin-mine" data-key="my-timesheet"><summary>My timesheet · ${plural(mine.length,'entry')}</summary><div class="table-scroll"><table><thead><tr><th>DAY</th><th>IN</th><th>OUT</th><th>WORKED</th><th>STATUS</th></tr></thead><tbody>${mine.map(x=>`<tr><td>${dateLabel(x.date,{weekday:'short',month:'short',day:'numeric'})}</td><td>${clock(x.in)}</td><td>${x.out?clock(x.out):'—'}</td><td>${P.counted(st,x,now)?span(P.counted(st,x,now)):'—'}</td><td>${badge(x.status==='Approved'?'Approved':x.out?'Waiting for approval':'On the clock',x.status==='Approved'?'tone-sage':'')}</td></tr>`).join('')}</tbody></table></div></details>`:''}<div class="fin-stubs"><h3>Pay stubs</h3>${stubs.length?stubs.slice(0,8).map(r=>{const l=r.lines.find(x=>x.person===id);return `<button type="button" class="fin-stub-row" data-action="fin-stub" data-id="${e(r.id)}"><span><strong>${dateLabel(r.payDate,{month:'short',day:'numeric',year:'numeric'})}</strong><small>${range(r.from,r.to)} · ${hrs(l.minutes)} h</small></span><span><strong>${money(l.gross)}</strong><small>${r.status==='Paid'?'Paid':'Processing'}</small></span></button>`;}).join(''):'<p class="table-detail">Your pay stubs will appear here after your first pay run.</p>'}</div></section>`;
 }
 function stub(r,id){
  const st=s(),l=r.lines.find(x=>x.person===id),p=st.team.find(x=>x.id===id),c=P.settings(st);
  const row=(label,qty,rate,amount)=>`<tr><td>${label}</td><td>${qty}</td><td>${rate}</td><td><strong>${money(amount)}</strong></td></tr>`;
  return `<div class="fin-stub"><div class="fin-stub-head"><div><small>${e(B.writeups?.restaurant||'')}</small><h3>${e(p?.name||'')}</h3><p>${e(p?.hr?.employeeId||'')} · ${range(r.from,r.to)}</p></div><div><small>Pay date</small><strong>${dateLabel(r.payDate,{month:'short',day:'numeric',year:'numeric'})}</strong>${badge(r.status==='Paid'?'Paid':'Processing',r.status==='Paid'?'tone-sage':'tone-orange')}</div></div><table><thead><tr><th>EARNINGS</th><th>HOURS</th><th>RATE</th><th>AMOUNT</th></tr></thead><tbody>${row('Regular',hrs(l.regMinutes),money(l.rate),l.regularPay)}${l.otMinutes?row('Overtime',hrs(l.otMinutes),money(l.rate*c.multiplier),l.overtimePay):''}${l.leaveMinutes?row('Paid leave',hrs(l.leaveMinutes),'',l.leavePay):''}</tbody><tfoot><tr><td colspan="3"><strong>Gross pay</strong></td><td><strong>${money(l.gross)}</strong></td></tr>${l.tips?`<tr><td colspan="3">Tips you declared (already received)</td><td>${money(l.tips)}</td></tr>`:''}</tfoot></table><p class="fin-note">Taxes and deductions are calculated by ${e(c.provider)}. Your net pay and tax details are on their statement.</p></div>`;
 }

 // The time clock as data for the Today hero: a state, a short label, one line of detail and the buttons. It runs on real time, whatever day the screen is showing.
 function clockState(){
  const st=s(),id=me(),now=P.stamp(),day=now.slice(0,10);
  const open=st.timeclock.entries.find(x=>x.person===id&&!x.out),done=st.timeclock.entries.filter(x=>x.person===id&&x.date===day&&x.out);
  const shift=st.shifts.filter(x=>x.person===id&&x.date>=B.addDays(day,-1)&&x.date<=B.addDays(day,1)&&!S.absence(st,x)&&!st.timeclock.entries.some(y=>y.shiftId===x.id)&&P.shiftTimes(x).end>now&&P.between(now,P.shiftTimes(x).start)<=720).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start))[0];
  const row=(state,label,detail,acts)=>({state,label,detail,acts,matchesShift:!!open&&st.shifts.some(x=>x.id===open.shiftId&&x.date===st.date&&x.service===st.service)});
  if(open){
   if(P.flags(st,open,now).some(f=>f.kind==='noout'))return row('review','Missing clock-out',`Started ${e(dateLabel(open.date))} at ${clock(open.in)} · ${manager()?'Correct the end time before continuing.':'Ask your manager to correct the end time.'}`,manager()?act('Fix time','edit',open.id):'');
   const br=P.onBreak(open);return row(br?'break':'on',br?'On break now':'On the clock now',`${span(P.worked(open,now))} worked · in at ${clock(open.in)}`,button(br?'End break':'Start break','tc-break','','','secondary')+button('Clock out','tc-out','','',''));
  }
  if(shift){const mins=P.between(now,P.shiftTimes(shift).start);return row('ready','Not clocked in',mins>0?'Clock in when you arrive · '+e(shift.service)+' at '+e(shift.start):'Your shift started '+span(-mins)+' ago',button('Clock in','tc-in','','',''));}
  if(done.length)return row('done','Clocked today',`${span(done.reduce((n,x)=>n+P.worked(x),0))} · ${done.map(x=>clock(x.in)+'–'+clock(x.out)).join(' · ')}`,button('Clock in again','tc-in','','','secondary'));
  return row('idle','Not clocked in','No shift right now · clocked time goes to your manager to approve',button('Clock in','tc-in','','','secondary'));
 }

 // Things the manager overview and Today should raise.
 function attention(){
  const st=s(),f=focus(st),r=P.readiness(st,f.from,f.to),now=P.stamp(),out=[];
  const stuck=st.timeclock.entries.filter(x=>!x.out&&P.flags(st,x,now).some(g=>g.kind==='noout'));
  for(const x of stuck)out.push({rank:0,tone:'danger',title:`${name(x.person)} never clocked out`,sub:`Clocked in ${dateLabel(x.date)} at ${clock(x.in)}. Fix it before payroll.`,acts:act('Fix','edit',x.id,'secondary small')});
  if(!f.run&&f.ended)out.push({rank:0,tone:'orange',title:`Payroll for ${range(f.from,f.to)} is ready to run`,sub:`${r.pending.length?plural(r.pending.length,'timesheet entry')+' to approve · ':''}pay date ${dateLabel(f.payDate,{weekday:'short',month:'short',day:'numeric'})}`,acts:button('Run payroll','mg-tab','payruns','','small')});
  else if(f.run?.status==='Approved')out.push({rank:1,tone:'orange',title:'Approved pay run waiting to be exported',sub:`${range(f.from,f.to)} · ${money(f.run.totals.gross)} gross`,acts:button('Export','mg-tab','payruns','','secondary small')});
  const open=B.biz?B.biz.openDays(st,B.addDays(today(),-7),today()):[];
  if(open.length)out.push({rank:0,tone:'orange',group:'today',title:open.length===1?`Close out ${dateLabel(open[0],{weekday:'long'})}`:`${plural(open.length,'day')} to close out`,sub:'Sales, guests, comps and cash. Everything else about the day is filled in.',acts:act('Close out','close',open[0],'small')});
  if(r.missing.length&&!f.run)out.push({rank:1,tone:'amber',title:plural(r.missing.length,'shift')+' with no clock-in',sub:r.missing.slice(0,3).map(x=>name(x.person).split(' ')[0]+' '+dateLabel(x.date)).join(' · '),acts:act('Review','go-ts',f.from,'secondary small')});
  return out;
 }
 const pendingCount=()=>{const st=s(),f=focus(st);return f.run?0:P.readiness(st,f.from,f.to).pending.length;};
 const runDue=()=>{const st=s(),f=focus(st);return (!f.run&&f.ended)||['Approved','Exported'].includes(f.run?.status);};

 function entryForm(x,gap,person){
  const st=s(),sh=x?st.shifts.find(y=>y.id===x.shiftId):gap,brk=x?(typeof x.breakMinutes==='number'?x.breakMinutes:(x.breaks||[]).reduce((n,b)=>n+(b.end?P.between(b.start,b.end):0),0)):(gap?.breakMinutes||0);
  const t=sh&&P.shiftTimes(sh),fin=x?.in||t?.start||P.stamp(),fout=x?.out||(x?'':t?.end||'');
  return `${x||gap?`<p><strong>${e(name(x?.person||gap.person))}</strong> · ${sh?`${dateLabel(sh.date,{weekday:'short',month:'short',day:'numeric'})} · ${e(sh.service)} ${sh.start}–${sh.end}`:'Unscheduled time'}</p>`:`<label>Team member<select name="person" required>${st.team.filter(p=>p.active).map(p=>`<option value="${e(p.id)}" ${p.id===person?'selected':''}>${e(p.name)}</option>`).join('')}</select></label>`}<div class="mg-form-grid"><label>Clock in<input type="datetime-local" name="in" value="${e(fin)}" required></label><label>Clock out<input type="datetime-local" name="out" value="${e(fout)}"></label><label>Unpaid break (minutes)<input type="number" name="breakMinutes" min="0" step="1" value="${brk}"></label></div><label>Reason for the change<input name="note" required maxlength="300" placeholder="e.g. Forgot to clock out, confirmed with the closing manager"></label>${x?'<label class="fin-remove"><input type="checkbox" name="remove" value="yes"> Remove this entry (duplicate or mistake)</label>':''}<p class="fin-note">Saving approves the entry and keeps the original times in its history.</p>${x?.edits?.length?`<details><summary>Change history · ${x.edits.length}</summary><ol class="task-activity">${x.edits.map(h=>`<li>${e(h.note)} · ${e(name(h.by))}<small>${new Date(h.at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} · was ${clock(h.before.in)}–${h.before.out?clock(h.before.out):'open'}</small></li>`).join('')}</ol></details>`:''}`;
 }
 function settingsForm(){
  const c=P.settings(s()),num=(n,label,v,attrs)=>`<label>${label}<input type="number" name="${n}" value="${v}" ${attrs}></label>`;
  return `<div class="mg-form-grid"><label>How often you pay<select name="frequency"><option value="biweekly" ${c.frequency==='biweekly'?'selected':''}>Every two weeks</option><option value="weekly" ${c.frequency==='weekly'?'selected':''}>Weekly</option></select></label>${num('payDelay','Pay date · days after the period ends',c.payDelay,'min="0" max="14" step="1" required')}${num('weeklyOvertime','Overtime after · hours a week',c.weeklyOvertime,'min="1" max="80" step="0.5" required')}${num('dailyOvertime','Overtime after · hours a day (0 = off)',c.dailyOvertime,'min="0" max="24" step="0.5"')}${num('multiplier','Overtime rate',c.multiplier,'min="1" max="3" step="0.05" required')}${num('employerTax','Employer taxes · estimate %',c.employerTax,'min="0" max="40" step="0.1" required')}${num('grace','Late after · minutes',c.grace,'min="0" max="30" step="1" required')}<label>Payroll provider<input name="provider" maxlength="60" value="${e(c.provider)}" placeholder="e.g. Gusto, ADP, Paychex"></label></div><p class="fin-note">Overtime follows the workweek, Monday to Sunday. Some states also require daily overtime; set the daily limit if yours does. Employer taxes are an estimate for planning: your provider calculates the real amounts.</p>`;
 }

 function handle(action,id,data={}){
  const st=s();
  if(action==='in'){api.commit({type:'clock:in',id:crypto.randomUUID()},'Clocked in at '+clock(P.stamp())+'.');return;}
  if(action==='break'){const open=st.timeclock.entries.find(x=>x.person===me()&&!x.out);api.commit({type:'clock:break'},open&&P.onBreak(open)?'Break ended.':'Break started. Enjoy it.');return;}
  if(action==='out'){api.commit({type:'clock:out'},'Clocked out at '+clock(P.stamp())+'. Thanks for today.');return;}
  if(action==='ts-period'){const p=P.period(st,tsFrom||focus(st).from);tsFrom=Number(id)<0?P.previousPeriod(st,p).from:P.period(st,B.addDays(p.to,1)).from;api.render();return;}
  if(action==='go-ts'){tsFrom=id||focus(st).from;api.go('timesheets');return;}
  if(action==='go-runs'){api.go('payruns');return;}
  if(action==='approve'){api.commit({type:'clock:approve',ids:[id]},'Entry approved.');return;}
  if(action==='approve-all'){const p=P.period(st,id),ids=st.timeclock.entries.filter(x=>x.date>=p.from&&x.date<=p.to&&x.out&&x.status!=='Approved').map(x=>x.id);api.commit({type:'clock:approve',ids},plural(ids.length,'entry')+' approved.');return;}
  if(action==='edit'){const x=st.timeclock.entries.find(y=>y.id===id);form={kind:'edit',id,person:x.person};api.form('Edit time · '+name(x.person),entryForm(x),'Save time');return;}
  if(action==='add'){const gap=st.shifts.find(y=>y.id===id);form={kind:'edit',id:crypto.randomUUID(),person:data.person||'',shiftId:gap?.id||''};api.form(gap?'Add time · '+name(gap.person):'Add time',entryForm(null,gap,data.person),'Save time');return;}
  if(action==='close'){form={kind:'close',date:id};api.form((st.business.closes[id]?'Daily close · ':'Close out · ')+dateLabel(id,{weekday:'long',month:'long',day:'numeric'}),closeForm(id),st.business.closes[id]?'Save changes':'Close the day');return;}
  if(action==='close-reopen'){api.commit({type:'close:reopen',date:id},'Day reopened.');return;}
  if(action==='credit'){api.commit({type:'credit:claim',id,claimed:data.claimed!=='true'},data.claimed==='true'?'Marked as not claimed.':'Credit marked as claimed.');return;}
  if(action==='sales-add'){
   const date=data.date||B.addDays(today(),-1),svc=data.service||st.setup.services.find(v=>v.active)?.name,old=st.business.sales.find(x=>x.date===date&&x.service===svc);form={kind:'sales'};
   api.form(old?'Edit sales':'Enter sales',`<div class="mg-form-grid"><label>Date<input type="date" name="date" value="${date}" required></label><label>Service<select name="service">${st.setup.services.map(v=>`<option ${v.name===svc?'selected':''}>${e(v.name)}</option>`).join('')}</select></label><label class="wide">Net sales ($)<input type="number" name="amount" min="0" step="0.01" value="${old?.amount??''}" required placeholder="From your POS end-of-day report"></label></div><p class="fin-note">Use net sales: after discounts and comps, before sales tax and tips. Entering the same service again replaces it.</p>`,'Save sales');return;
  }
  if(action==='settings'){form={kind:'settings'};api.form('Pay settings',settingsForm(),'Save pay settings');return;}
  if(action==='approve-run'){const p=P.period(st,id),r=P.readiness(st,p.from,p.to),t=P.calc(st,p.from,p.to).totals;form={kind:'approve',from:p.from};api.form('Approve pay run · '+range(p.from,p.to),`<div class="fin-confirm"><p>This locks the hours for ${range(p.from,p.to)} and creates the pay run.</p><ul><li><strong>${t.people}</strong> people · <strong>${hrs(t.minutes)}</strong> hours · <strong>${hrs(t.otMinutes)}</strong> overtime</li><li>Gross pay <strong>${money(t.gross)}</strong> · total labor cost about <strong>${money(t.cost)}</strong></li>${r.pending.length?`<li>${plural(r.pending.length,'timesheet entry')} will be approved with it</li>`:''}${r.missing.length?`<li class="warn">${plural(r.missing.length,'shift')} still have no clock-in and won’t be paid</li>`:''}</ul></div>`,'Approve pay run');return;}
  if(action==='export'){const r=st.payroll.runs.find(x=>x.id===id),provider=exportRun(r);api.commit({type:'payroll:export',id},`Payroll file downloaded. Upload it to ${provider}.`);return;}
  if(action==='download'){exportRun(st.payroll.runs.find(x=>x.id===id));return;}
  if(action==='paid'){api.commit({type:'payroll:paid',id},'Pay run marked as paid.');return;}
  if(action==='reopen'){api.commit({type:'payroll:reopen',id},'Pay run reopened. Its hours can be edited again.');return;}
  if(action==='run'){const r=st.payroll.runs.find(x=>x.id===id);api.open('Pay run · '+range(r.from,r.to),`<div class="fin-run-detail"><div class="fin-tiles"><div><small>Pay date</small><strong>${dateLabel(r.payDate,{month:'short',day:'numeric'})}</strong><em>${e(r.status)}</em></div><div><small>Hours</small><strong>${hrs(r.totals.minutes)}</strong><em>${hrs(r.totals.otMinutes)} overtime</em></div><div><small>Gross pay</small><strong>${money(r.totals.gross)}</strong></div><div class="is-total"><small>Total cost</small><strong>${money(r.totals.cost)}</strong></div></div>${linesTable(r)}<div class="card-actions">${act('Download payroll file','download',r.id,'secondary')}</div></div>`);return;}
  if(action==='stub'){const r=st.payroll.runs.find(x=>x.id===id);api.open('Pay stub',stub(r,me()));}
 }
 function submit(v){
  if(!form)throw Error('Reopen the form.');
  form.saved={close:'Day closed. Reports are up to date.',sales:'Sales saved. Labor % and prime cost are updated.',settings:'Pay settings saved.',approve:'Pay run approved. Export it for your payroll provider next.'}[form.kind]||(v.remove==='yes'?'Time entry removed.':'Time saved and approved.');
  if(form.kind==='close')return {type:'close:save',date:form.date,sales:Object.fromEntries(Object.entries(v).filter(([k])=>k.startsWith('sales_')).map(([k,x])=>[k.slice(6),x])),specials:Object.fromEntries(Object.entries(v).filter(([k])=>k.startsWith('sold_')).map(([k,x])=>[k.slice(5),x])),guests:v.guests,comps:v.comps,cash:v.cash,notes:v.notes};
  if(form.kind==='sales')return {type:'sales:put',date:v.date,service:v.service,amount:Number(v.amount)};
  if(form.kind==='settings')return {type:'payroll:settings',...v};
  if(form.kind==='approve')return {type:'payroll:approve',from:form.from,approveTimesheets:true};
  if(v.remove==='yes')return {type:'clock:delete',id:form.id,note:v.note};
  return {type:'clock:edit',id:form.id,person:v.person||form.person,shiftId:form.shiftId||'',in:v.in,out:v.out||'',breakMinutes:Number(v.breakMinutes||0),note:v.note};
 }
 return {saved:()=>form?.saved||'',daily,inventory,overtimeWatch,laborSplit,timesheets,payruns,myPay,clockState,attention,pendingCount,runDue,focus,handle,submit,showPeriod:from=>{tsFrom=from;}};
};
